package com.umc.pediupatrao.audit;
import org.springframework.security.core.Authentication; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import java.time.Instant; import java.util.Map;
@Service public class AuditoriaService {private final AuditoriaRepository repo; public AuditoriaService(AuditoriaRepository repo){this.repo=repo;} public void registrar(String op,String entidade,String id,Map<String,Auditoria.Alteracao> campos,String justificativa){Authentication a=SecurityContextHolder.getContext().getAuthentication();String user=a==null?"sistema":a.getName();String perfil="ANONIMO";if(a!=null&&a.getAuthorities()!=null)perfil=a.getAuthorities().stream().map(x->x.getAuthority().replace("ROLE_","")).sorted().findFirst().orElse("USUARIO");repo.save(new Auditoria(user,perfil,Instant.now(),op,entidade,id,campos,justificativa));} public java.util.List<Auditoria> listar(){return repo.findAll();}}
